'use strict';
window.BD_REVIEW_DATA={"limits": {"tel-dan": "An enemy king knew Judah’s dynasty as the House of David, about 150 years after David’s lifetime. The stone supports a historical Davidic dynasty; the size of David’s kingdom needs other evidence.", "nimrud": "Assyria names Jehu and records his tribute in 841 BC. The kneeling figure could be Jehu or his envoy. “Son of Omri” identifies Israel in Assyrian usage; Jehu was not Omri’s biological son.", "babylon": "Cyrus describes restoring shrines and displaced communities after taking Babylon. That policy fits the return recorded in Ezra. The cylinder concerns other communities; Ezra names the Jewish return and Jerusalem.", "thebes": "An Egyptian ruler named Israel as a people in Canaan by about 1208 BC. That gives us a firm point on Israel’s timeline; the date of their arrival requires further evidence.", "qumran": "The same recognizable book of Isaiah survives about a thousand years earlier than the complete medieval Hebrew copies. Isaiah 53 was there before Jesus. The copies also contain variants that scholars can compare openly.", "avaris": "Levantine families really lived in Egypt’s Delta, the cultural world Genesis describes. Connecting a particular house or official with Joseph remains a proposal: no inscription here names him, and the proposed dates need careful comparison.", "galilee": "This boat comes from Jesus’s lake and roughly his period. Its planks and repairs bring the Gospel fishing world into view. Its particular owner and passengers remain unknown.", "bethesda": "The excavated double pools explain John’s unusual five walkways. This supports his knowledge of Jerusalem and gives us reason to take his account seriously. John supplies the testimony about the healing.", "caesarea": "The stone confirms Pontius Pilate’s name and office in Roman Judea. The Gospels place him there in Jesus’s trial. His building dedication and the written accounts give us different evidence about the same governor.", "delphi": "Claudius’s letter dates Gallio’s office to around AD 51–52. Acts names that same proconsul at Paul’s hearing. Together they anchor Paul’s Corinth visit to a narrow historical window.", "oxyrhynchus": "These early Gospel copies let us examine how the text was transmitted. Handwriting suggests a date range, and comparing copies exposes variations. Read the preserved text alongside the early eyewitness testimony behind its accounts.", "megiddo": "The mosaic names a woman who gave the table and addresses God Jesus Christ before Nicaea in AD 325. Its precise third-century date is debated. Four other women are remembered by name; their particular roles are not specified."}, "hooks": {"babylon": "A conqueror sends communities home. Compare his policy with Ezra.", "galilee": "Two brothers spotted an ancient boat when drought lowered the lake.", "bethesda": "Why did John count five walkways? Look at the two pools.", "caesarea": "The governor in Jesus’s trial put his name on a public building.", "delphi": "A letter to Delphi helps date Paul’s visit to Corinth.", "oxyrhynchus": "A rubbish dump preserved pages of the Gospels."}, "sources": {"tel-dan": [{"label": "Tel Dan excavation project", "locator": "Object / excavation record", "url": "https://ngsba.org/excavations/tel-dan/", "note": "The excavation records the recovery of inscribed basalt fragments in 1993–1994. The royal-house reading connects an Aramaic enemy monument with Judah’s dynasty."}, {"label": "Scripture comparison", "locator": "2 Kings 8:28–9:28", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Grisanti, OT796 appendix #96; references below", "url": "", "note": "Grisanti’s appendix #96 reproduces the inscription and points to Price & House, p. 119. Beck, p. 130, entry 21, also identifies the House of David. The excavation publications are Biran & Naveh, Israel Exploration Journal 43 (1993), 81–98, and 45 (1995), 1–18."}], "nimrud": [{"label": "University of Pennsylvania · Nimrud project", "locator": "Object / excavation record", "url": "https://oracc.museum.upenn.edu/nimrud/livesofobjects/blackobelisk/index.html", "note": "The Nimrud project explains the monument’s five tribute registers and its caption naming Jehu. An Assyrian royal monument is a witness from outside Israel."}, {"label": "Scripture comparison", "locator": "2 Kings 9–10", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Grisanti, OT796 appendix #82; references below", "url": "", "note": "Grisanti’s appendix #82 presents the tribute scene and credits Alfred Hoerth, Archaeology and the Old Testament, p. 322. Price & House’s chart on p. 198 also lists it, but its findspot/date row needs checking against the excavation record: Nimrud, 1846."}], "babylon": [{"label": "British Museum · Cyrus Cylinder", "locator": "Object / excavation record", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "note": "The British Museum identifies the cylinder as a royal foundation inscription from Babylon. Read its restoration language as Cyrus’s public account of his reign."}, {"label": "Scripture comparison", "locator": "Ezra 1:1–4; 6:3–5 · Isaiah 44:28–45:1", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Grisanti, OT796 appendix #87; references below", "url": "", "note": "Grisanti’s appendix #87 supplies a translation excerpt credited to Mordechai Cogan, “Cyrus Cylinder (2.124),” The Context of Scripture, vol. 2, pp. 315–316. That excerpt concerns Mesopotamian restorations. Price & House, p. 198, gives a broad biblical connection; the object itself does not name Jerusalem."}], "thebes": [{"label": "Michael G. Hasel · Israel in the Merneptah Stela", "locator": "Bulletin of the American Schools of Oriental Research 296 (1994): 45–61. DOI 10.2307/1357179. Publisher abstract consulted.", "url": "https://doi.org/10.2307/1357179", "note": "Hasel’s analysis identifies Israel as a people within Canaan. The text and its grammatical markers give evidence for Israel outside the biblical account around 1208 BC. His abstract dates the stele approximately to 1207 BC; the game rounds to the conventional circa-1208 date."}, {"label": "Scripture comparison", "locator": "Judges 2:6–15", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Grisanti, OT796 appendix #79; references below", "url": "", "note": "Grisanti’s appendix #79 discusses the Israel reference and cites Michael Hasel and John Bimson. Beck, p. 128, entry 12, identifies Israel on the stele. Dates in the supplied charts vary; the game uses the conventional date of about 1208 BC."}], "qumran": [{"label": "Israel Museum · The Great Isaiah Scroll", "locator": "Object / excavation record", "url": "https://www.imj.org.il/sites/default/files/IMJ%20Great%20Isaiah%20Scroll%20Exhibition.pdf", "note": "The Israel Museum’s presentation identifies 1QIsaᵃ as a complete Isaiah manuscript copied about 125 BC. The suffering-servant passage therefore predates Christianity."}, {"label": "Scripture comparison", "locator": "Isaiah 52:13–53:12 · Luke 4:16–21 · Acts 8:26–35", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Grisanti, OT796 appendix #100; references below", "url": "", "note": "Grisanti’s appendix #100 places the Isaiah scroll among the manuscript evidence. The Israel Museum and Israel Antiquities Authority describe the manuscript and its discovery directly. Compare wording as well as spelling; an old copy is stronger evidence when its differences are available for inspection."}], "avaris": [{"label": "Austrian excavation project · site history", "locator": "Object / excavation record", "url": "https://auaris.at/html/history_en.html", "note": "The Austrian excavation describes the settlement’s Levantine contacts through buildings, pottery, burials and other material. Those are observations before any identification with a biblical individual."}, {"label": "Scripture comparison", "locator": "Genesis 46–47; Exodus 1", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Grisanti, OT796 appendix #77; references below", "url": "", "note": "Grisanti’s notes, printed p. 155 (PDF p. 156), acknowledge differing evangelical Exodus chronologies. His appendix #77 presents the Beni Hasan painting, a separate example of travel between the Levant and Egypt. It is contextual evidence, not a picture of Joseph’s family. Try the Investigation table to compare claims."}], "galilee": [{"label": "Yigal Allon Center · The Ancient Boat", "locator": "Object / excavation record", "url": "https://en.yigal-allon-centre.org.il/the-ancient-boat/", "note": "The Yigal Allon Center presents the boat recovered near Ginosar in 1986. Its timber, construction and conservation illuminate ancient fishing on the lake."}, {"label": "Scripture comparison", "locator": "Mark 4:35–41; Luke 5:1–11", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Israel Antiquities Authority · archaeological publications", "url": "https://www.antiquities.org.il/", "note": "The boat’s date range overlaps Jesus’s period. The Gospel connection is a comparison of setting, not an inscription identifying its passengers. Mark 4:35–41 and John 21 describe life on this same lake."}], "bethesda": [{"label": "Studium Biblicum Franciscanum · Bethesda field notes (Italian PDF)", "locator": "Object / excavation record", "url": "https://sbf.custodia.org/sites/default/files/2025-04/CABT%202025%20Visita%2022%20aprile%20-%20Betesda%20Sintesi.pdf", "note": "The Studium Biblicum Franciscanum’s archaeological account describes the pools and the site’s successive phases. The double-pool arrangement explains an otherwise unusual count."}, {"label": "Scripture comparison", "locator": "John 5:1–15", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Stand to Reason · Gospel settings", "url": "https://www.str.org/w/three-pieces-of-evidence-that-corroborate-the-gospels", "note": "John 5:2 describes five porticoes near the Sheep Gate. Compare that specific claim with the archaeology. The historical argument is that the writer knew a real setting; the healing is assessed through John’s testimony and the wider case for Jesus."}], "caesarea": [{"label": "University of Grenoble · Pilate inscription and bibliography", "locator": "Object / excavation record", "url": "https://droitromain.univ-grenoble-alpes.fr/Varia/Pontius_Pilatus_AE.htm", "note": "The published Latin text preserves Pilate’s name and prefect’s title. The Israel Museum’s record documents the object; the Grenoble edition supplies transcription and bibliography."}, {"label": "Scripture comparison", "locator": "Luke 3:1; John 18–19", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Israel Museum · collection record", "url": "https://www.imj.org.il/en/collections/393029-0", "note": "Compare Luke 3:1 and the Passion accounts. Tacitus, Annals 15.44, is a further Roman literary witness to Christ’s execution under Pilate. This is a separate source, not text carved on the stone."}], "delphi": [{"label": "Gallio inscription · Greek text, translation, and bibliography", "locator": "Object / excavation record", "url": "https://kchanson.com/ANCDOCS/greek/gallio.html", "note": "Claudius’s letter names Gallio as proconsul of Achaia. Its imperial titles constrain the date; published text and bibliography are available in the inscription edition."}, {"label": "Scripture comparison", "locator": "Acts 18:1–17", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "Delphi Archaeological Museum", "url": "https://delphi.culture.gr/", "note": "Acts 18:12–17 names Gallio in the same office when Paul is brought before him. The date depends on comparing that account with the inscription and the likely term of office, rather than finding Paul’s name on the stone."}], "oxyrhynchus": [{"label": "Oxford · The Oxyrhynchus Papyri", "locator": "Object / excavation record", "url": "https://oxyrhynchus.web.ox.ac.uk/site-excavations-and-finds", "note": "Oxford’s project describes the excavations and continuing publication of papyri from the ancient city. These include Christian writings alongside ordinary documents."}, {"label": "Scripture comparison", "locator": "Luke 1:1–4; 2 Timothy 4:13", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "British Academy · papyri research project", "url": "https://www.thebritishacademy.ac.uk/projects/academy-research-projects-oxyrhynchus-papyri/", "note": "A manuscript’s handwriting normally supports a range rather than an exact year. Comparing surviving witnesses helps recover wording. Luke 1:1–4 and 1 Corinthians 15:3–8 address the earlier investigation and testimony behind the Christian accounts."}], "megiddo": [{"label": "Museum of the Bible · the three inscriptions", "locator": "Object / excavation record", "url": "https://www.museumofthebible.org/the-inscriptions", "note": "The inscriptions name Akeptous as the table’s donor and Gaianus as the mosaic’s benefactor. Another inscription remembers four women. The dedication addresses God Jesus Christ."}, {"label": "Scripture comparison", "locator": "John 20:28; Philippians 2:5–11", "url": "", "note": "The biblical passage supplies the account being compared. A museum catalog and a Christian interpretation answer different questions; the comparison is explained on this card."}, {"label": "Reading and source trail", "locator": "IAA publication · Tepper & Di Segni, 2006", "url": "https://www.academia.edu/13120070/Tepper_Y_Pl_and_Di_Segni_L_Pl_2006_A_Christian_Prayer_Hall_of_the_3rd_Century_CE_At_Kfar_%CA%BBOthnai_Legio_excavations_at_the_Megiddo_Prison_2005_Israel_Antiquities_Authority_1_59_", "note": "Tepper & Di Segni, A Christian Prayer Hall of the 3rd Century CE at Kefar ʿOthnay (Legio), Israel Antiquities Authority, 2006, is the excavation publication. The museum provides an accessible presentation. A third-century date places the dedication before Nicaea; the exact interval is debated."}], "ketef": [{"label": "Barkay, Lundberg, Vaughn & Zuckerman", "locator": "The Amulets from Ketef Hinnom: A New Edition and Evaluation. BASOR 334 (2004), 41–71. DOI 10.2307/4150106. Abstract consulted; full paper not obtained.", "url": "https://doi.org/10.2307/4150106", "note": "The authors’ new high-resolution reading places the silver amulets in the late preexilic period. They identify wording also preserved in the Hebrew Bible."}, {"label": "Numbers 6:24–26", "locator": "The priestly blessing; compare the surviving ancient wording", "url": "", "note": "The amulets preserve forms of the blessing, not a modern English translation or an entire book of the Bible."}, {"label": "Discovery and course trail", "locator": "Gabriel Barkay’s interview with Gila Yudkin; Grisanti notes pp. 156–157 (PDF pp. 157–158), appendix #98. Beck, p. 134, entry 43.", "url": "https://www.itsgila.com/highlightspriestly.htm", "note": "Barkay recalls junior-high volunteers at the 1979 dig. Nathan’s discovery brought attention to a repository. The account is retrospective, distinct from the published inscription analysis."}]}, "bibliography": [["Michael A. Grisanti", "OT796 OT Introduction, Spring 2026 course notes, pp. 155–158, 162, 166–167; companion appendix #77, 79, 82, 87, 96, 98, 100. Supplied privately; page numbers here are printed numbers. Appendix numbers follow the appendix PDF, not the notes."], ["Michael A. Grisanti", "“Recent Archaeological Discoveries That Lend Credence to the Historicity of the Scriptures.” Journal of the Evangelical Theological Society 56/3 (2013): 475–497, especially 475–476. Published article consulted for the interpretive method."], ["John A. Beck", "The Baker Book of Bible Charts, Maps, and Time Lines. Baker Books, 2016. Supplied chart excerpt, pp. 126–135 plus the title leaf; specific entries identified above. Facts paraphrased; pages and photographs not reproduced."], ["J. Randall Price and H. Wayne House", "Zondervan Handbook of Biblical Archaeology. Zondervan, 2017. Supplied excerpt, pp. 194–200, especially chart p. 198. Some chart dates and findspots conflict with object records; the game follows the object records. Their p. 119 is cited through Grisanti’s appendix #96, not through this supplied excerpt."], ["Avraham Biran and Joseph Naveh", "“An Aramaic Stele Fragment from Tel Dan.” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment.” IEJ 45 (1995): 1–18. Bibliographic trail; the originals were not obtained for this update."], ["Alfred J. Hoerth", "Archaeology and the Old Testament. Baker Books, 1998, p. 322. Cited through Grisanti appendix #82; book page not independently obtained."], ["Mordechai Cogan", "“Cyrus Cylinder (2.124).” In The Context of Scripture, edited by William W. Hallo and K. Lawson Younger Jr., vol. 2. Brill, 2000, pp. 315–316. Translation excerpt consulted through Grisanti appendix #87."], ["Edwin M. Yamauchi", "The Stones and the Scriptures. J. B. Lippincott, 1972, pp. 146–157, calculation p. 156. The five fractions are an illustrative estimate, cited through Grisanti notes pp. 166–167; the original book was not obtained."], ["Gabriel Barkay, Marilyn J. Lundberg, Andrew G. Vaughn, Bruce Zuckerman", "“The Amulets from Ketef Hinnom: A New Edition and Evaluation.” Bulletin of the American Schools of Oriental Research 334 (2004): 41–71. DOI 10.2307/4150106. Publisher abstract consulted."], ["Eusebius / Papias", "Ecclesiastical History 3.39.15, quoting Papias on Mark and Peter. Ancient testimony, consulted in the published New Advent translation."], ["Yotam Tepper and Leah Di Segni", "A Christian Prayer Hall of the 3rd Century CE at Kefar ʿOthnay (Legio): Excavations at the Megiddo Prison 2005. Israel Antiquities Authority, 2006. Publication trail; the museum’s inscription presentation was consulted directly."], ["Michael G. Hasel", "“Israel in the Merneptah Stela.” Bulletin of the American Schools of Oriental Research 296 (1994): 45–61. DOI 10.2307/1357179. Publisher abstract consulted for the name, region and nature of Israel in the inscription."]]};
